// The cockpit is the only caller. A shared secret in a header is the whole
// gate, so it is compared in constant time -- a plain === leaks the length
// of the matching prefix through timing, and this endpoint sends WhatsApp
// messages on a client's behalf.
const crypto = require('crypto');
const req = $input.first().json;
const headers = req.headers || {};
const given = String(headers['x-ryvo-cockpit-secret'] || '');
const want  = String($env.COCKPIT_SEND_SECRET || '');

let authed = false;
if (want && given.length === want.length) {
  authed = crypto.timingSafeEqual(Buffer.from(given), Buffer.from(want));
}

// Never echo either value, not even a prefix, and not into an execution
// that is retained for 14 days.
const body = req.body || {};
return [{ json: {
  authed,
  secretConfigured: Boolean(want),
  leadId: String(body.leadId || ''),
  text: String(body.text || ''),
} }];

// The caller supplies a lead id and nothing else. The DESTINATION NUMBER is
// resolved here, from the row, and never taken from the request -- otherwise
// anyone holding the secret could send a WhatsApp message to any number in
// the world on the client's account.
const a   = $('CheckSecret').first().json;
const res = $input.first().json;
const rows = Array.isArray(res.body) ? res.body : [];
const lead = rows[0] || null;

const text = String(a.text || '').trim();

let error = null;
if (res.statusCode < 200 || res.statusCode >= 300) error = 'lead_lookup_failed:' + res.statusCode;
else if (!lead) error = 'lead_not_found';
else if (!lead.phone) error = 'lead_has_no_phone';
else if (!text) error = 'empty_text';
else if (text.length > 1500) error = 'text_too_long';

return [{ json: {
  ok: error === null,
  error,
  leadId: a.leadId,
  clientId: lead ? lead.client_id : null,
  phone: lead ? lead.phone : null,
  name: lead ? lead.full_name : null,
  text,
} }];

// Same shape as the Concierge's AfterSend. neverError turns a 4xx into a
// green node, so the status is read explicitly rather than inferred from
// the node having run -- instance 13.
const p   = $('AfterLoad').first().json;
const res = $input.first().json;
const ok  = res.statusCode >= 200 && res.statusCode < 300;
const b   = res.body || {};
return [{ json: { ...p,
  sendOk: ok,
  twilioSid: ok ? (b.sid || null) : null,
  twilioErrorCode: ok ? null : (b.code || res.statusCode),
  twilioErrorMessage: ok ? null : String(b.message || '').slice(0, 300),
} }];

// A node whose whole purpose is to write a row must have its status
// surfaced -- #6 in the lessons file recurred verbatim three days after
// being written up, both times caught by checking the artefact rather than
// the execution. So the cockpit is told whether the row exists, separately
// from whether Twilio accepted the message.
const p   = $('AfterSend').first().json;
const res = $input.first().json;
const stored = res.statusCode >= 200 && res.statusCode < 300;

return [{ json: {
  ok: p.sendOk && stored,
  sendOk: p.sendOk,
  stored,
  storeStatus: res.statusCode,
  storeError: stored ? null : String(JSON.stringify(res.body || {})).slice(0, 300),
  sid: p.twilioSid,
  error: p.sendOk ? (stored ? null : 'message_not_recorded') : ('send_failed:' + (p.twilioErrorCode || 'unknown')),
  errorMessage: p.sendOk ? null : p.twilioErrorMessage,
} }];
